const raw = $input.first().json.content[0].text;
const s0 = raw.indexOf("{"); const e0 = raw.lastIndexOf("}");
const data = JSON.parse(raw.slice(s0, e0 + 1));
const TOTAL = 15;
let scenes = Array.isArray(data.scenes) ? data.scenes.slice(0, 4) : [];
if (scenes.length === 0) { scenes = [{ id:1, vo_segment:data.voiceover||"", on_screen_text:"", visual:{query:(data.meta&&data.meta.title)||"crypto news"}, duration_sec:TOTAL }]; }
scenes.forEach(function(s,i){ let d=Math.round(Number(s.duration_sec)); if(!(d>0)) d=Math.floor(TOTAL/scenes.length); s.duration_sec=d; s.id=i+1; s.image_prompt=(s.visual&&s.visual.query)?s.visual.query:((data.meta&&data.meta.title)||"crypto news"); });
const diff = TOTAL - scenes.reduce(function(a,s){return a+s.duration_sec;},0);
scenes[scenes.length-1].duration_sec += diff;
if (scenes[scenes.length-1].duration_sec < 1) scenes[scenes.length-1].duration_sec = 1;
const ts = Date.now();
scenes.forEach(function(s,i){ s.imageFile = "img_"+ts+"_"+(i+1)+".png"; });
data.scenes = scenes;
data.voiceFile = "voice_"+ts+".mp3";
data.outputFile = "video_"+ts+".mp4";
data.jobFile = "job_"+ts+".json";
let btc_price=null, btc_change_24h=null;
try { const _p = await this.helpers.httpRequest({ url: 'https://api.coingecko.com/api/v3/simple/price?ids=bitcoin&vs_currencies=usd&include_24hr_change=true', json: true }); if (_p && _p.bitcoin) { btc_price = Math.round(_p.bitcoin.usd); btc_change_24h = Math.round(_p.bitcoin.usd_24h_change * 10) / 10; } } catch (e) {}
var VALID_TICKERS = ["btc","sol","eth","xrp","ada","bnb","usdt","doge"];
var ticker = (data.ticker || "").toLowerCase();
if (VALID_TICKERS.indexOf(ticker) === -1) ticker = "";
let _wiki_dbg = [];
const UA = { 'User-Agent': 'CryptoNewsFactory/1.0 (news bot; contact@example.com)' };
const TICKER_TO_ID = { btc:'bitcoin', eth:'ethereum', sol:'solana', xrp:'ripple', ada:'cardano', bnb:'binancecoin', usdt:'tether', doge:'dogecoin' };
const HTTP = (o) => this.helpers.httpRequest(o);
const norm = (s) => (s || '').toLowerCase().replace(/[^a-z0-9]/g, '');
const wikiImage = async (title) => {
  if (!title) return null;
  try {
    const u = 'https://en.wikipedia.org/w/api.php?action=query&format=json&redirects=1&prop=pageimages&piprop=thumbnail&pithumbsize=600&titles=' + encodeURIComponent(title);
    const d = await HTTP({ url: u, json: true, headers: UA });
    const pages = d && d.query && d.query.pages;
    if (pages) { for (const k in pages) { const pg = pages[k]; if (pg.thumbnail && pg.thumbnail.source) return pg.thumbnail.source; } }
  } catch (e) { _wiki_dbg.push('wErr:' + title); }
  return null;
};
const companyLogo = async (title) => {
  if (!title) return null;
  try {
    const u1 = 'https://en.wikipedia.org/w/api.php?action=query&format=json&redirects=1&prop=pageprops&ppprop=wikibase_item&titles=' + encodeURIComponent(title);
    const d1 = await HTTP({ url: u1, json: true, headers: UA });
    const pages = d1 && d1.query && d1.query.pages; let qid = null;
    if (pages) { for (const k in pages) { if (pages[k].pageprops && pages[k].pageprops.wikibase_item) qid = pages[k].pageprops.wikibase_item; } }
    if (!qid) return null;
    const u2 = 'https://www.wikidata.org/w/api.php?action=wbgetclaims&format=json&property=P154&entity=' + encodeURIComponent(qid);
    const d2 = await HTTP({ url: u2, json: true, headers: UA });
    const cl = d2 && d2.claims && d2.claims.P154;
    if (cl && cl[0] && cl[0].mainsnak && cl[0].mainsnak.datavalue) {
      const fn = cl[0].mainsnak.datavalue.value;
      return 'https://commons.wikimedia.org/wiki/Special:FilePath/' + encodeURIComponent(fn) + '?width=600';
    }
  } catch (e) { _wiki_dbg.push('logoErr:' + title); }
  return null;
};
const cgEntity = async (name) => {
  const q = norm(name); if (!q) return null;
  const ok = (cand) => { const n = norm(cand); return n && (n === q || n.includes(q) || q.includes(n)); };
  try {
    const d = await HTTP({ url: 'https://api.coingecko.com/api/v3/search?query=' + encodeURIComponent(name), json: true });
    if (d && d.coins && d.coins[0] && (ok(d.coins[0].name) || ok(d.coins[0].id)) && d.coins[0].large) return d.coins[0].large;
    if (d && d.exchanges && d.exchanges[0] && (ok(d.exchanges[0].name) || ok(d.exchanges[0].id))) {
      const ex = d.exchanges[0];
      if (ex.large) return ex.large;
      if (ex.id) { try { const e = await HTTP({ url: 'https://api.coingecko.com/api/v3/exchanges/' + encodeURIComponent(ex.id), json: true }); if (e && e.image) return e.image; } catch (_) {} }
      if (ex.thumb) return ex.thumb;
    }
  } catch (e) { _wiki_dbg.push('cgErr:' + name); }
  return null;
};
const coinLogo = async (id) => {
  if (!id) return null;
  try {
    const u = 'https://api.coingecko.com/api/v3/coins/' + encodeURIComponent(id) + '?localization=false&tickers=false&market_data=false&community_data=false&developer_data=false&sparkline=false';
    const d = await HTTP({ url: u, json: true });
    if (d && d.image && (d.image.large || d.image.small)) return d.image.large || d.image.small;
  } catch (e) { _wiki_dbg.push('coinErr:' + id); }
  return null;
};
const resolveNonPerson = async (name) => {
  if (!name) return null;
  let img = await companyLogo(name);
  if (!img) img = await wikiImage(name);
  if (!img) img = await cgEntity(name);
  return img;
};
const MONTHS = ['January','February','March','April','May','June','July','August','September','October','November','December'];
const STOP = new Set(['The','A','An','This','That','These','Those','It','Its','They','He','She','We','You','But','And','So','Now','Then','After','Before','Meanwhile','However','Also','India','China','Japan','Korea','America','American','US','USA','UK','EU','Europe','Asia','Africa','Russia','Crypto','Cryptocurrency','Bitcoin','Ethereum','Blockchain','Exchange','Exchanges','Wallet','Wallets','CEO','CFO','CTO','Million','Billion','Trillion','Address','Hack','Token','Tokens','Stablecoin','Coin','Report','Reuters','Bloomberg','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'].concat(MONTHS));
const looksPerson = (n) => /^[A-Z][a-z]+ [A-Z][a-z]+$/.test(n);
const extractEntities = (vo) => {
  if (!vo) return []; const out = []; const seen = new Set();
  const add = (x) => { x = (x || '').trim(); if (x && x.length > 1 && !seen.has(x) && !STOP.has(x)) { seen.add(x); out.push(x); } };
  let m; const reBrand = /\b([A-Za-z]*[A-Z][A-Za-z]*[A-Z][A-Za-z0-9]*)\b/g; while ((m = reBrand.exec(vo))) add(m[1]);
  const reMulti = /\b([A-Z][a-z]+(?:\s+[A-Z][a-z]+)+)\b/g; while ((m = reMulti.exec(vo))) add(m[1]);
  const reSingle = /\b([A-Z][a-z]{2,})\b/g; while ((m = reSingle.exec(vo))) add(m[1]);
  return out;
};
for (const _s of scenes) {
  let c = _s.center; if (!c || !c.type) { _s.center = { type: 'none' }; c = _s.center; }
  if (c.type === 'stat') continue;
  if (c.type === 'coin') {
    const id = c.coingecko_id || TICKER_TO_ID[(c.ticker || '').toLowerCase()] || TICKER_TO_ID[(c.symbol || '').toLowerCase()] || '';
    let lg = id ? await coinLogo(id) : null; if (!lg) lg = await cgEntity(c.name || c.coingecko_id || c.ticker || c.symbol || '');
    if (lg) { c.logo_url = lg; _wiki_dbg.push('coinIMG:' + (id || c.name)); } else { _wiki_dbg.push('coinNo:' + (id || c.name)); }
    continue;
  }
  if (c.type === 'entity') {
    const title = (c.wiki && c.wiki !== 'none') ? c.wiki : (c.name || '');
    const isPerson = c.kind === 'person';
    _wiki_dbg.push('ent:' + title);
    let img = isPerson ? (await wikiImage(title) || (c.name && c.name !== title ? await wikiImage(c.name) : null)) : await resolveNonPerson(title);
    if (!img && !isPerson && c.name && c.name !== title) img = await resolveNonPerson(c.name);
    if (img) { c.logo_url = img; _wiki_dbg.push('entIMG:' + title); } else { _wiki_dbg.push('entDROP:' + title); _s.center = { type: 'none' }; c = _s.center; }
  }
  if (c.type === 'none') {
    const cands = extractEntities(_s.vo_segment).slice(0, 6);
    for (const e of cands) {
      _wiki_dbg.push('net:' + e);
      const img = await resolveNonPerson(e);
      if (img) { _s.center = { type: 'entity', kind: looksPerson(e) ? 'person' : 'company', name: e, wiki: e, logo_url: img }; _wiki_dbg.push('netIMG:' + e); break; }
    }
  }
}
const job = { comp:"main", voice:"assets/"+data.voiceFile, output:"outputs/"+data.outputFile, ticker: ticker, voiceover: data.voiceover || "", wiki_dbg: _wiki_dbg, btc_price: btc_price, btc_change_24h: btc_change_24h, scenes: scenes.map(function(s){return {image:"assets/"+s.imageFile, duration:s.duration_sec, on_screen_text: s.on_screen_text || "", image_prompt: s.image_prompt || "", center: s.center || {type:"none"}, vo_segment: s.vo_segment || ""};}) };
data.job_json = JSON.stringify(job);
const NL=String.fromCharCode(10), Q=String.fromCharCode(34);
const lines = scenes.map(function(s,i){ return (i+1)+". ("+s.duration_sec+"s) "+s.vo_segment+"  [img: "+s.image_prompt+"]"; });
data.script_text = ["🎬 "+((data.meta&&data.meta.title)||""),"",Q+(data.voiceover||"")+Q,"","Scenes:",lines.join(NL),"",(data.hashtags||[]).join(" ")].join(NL);
return [{ json: data }];

const txt = $('Add Captions').first().json.job_json;
const name = $('Code in JavaScript').first().json.jobFile;
const bin = await this.helpers.prepareBinaryData(Buffer.from(txt, 'utf8'), name, 'application/json');
return [{ json: { jobFile: name }, binary: { data: bin } }];

const align = $('Align').first().json || {};
const words = (align.words || []).filter(w => w && typeof w.text === 'string' && w.text.trim().length);
const captions = words.map(w => ({ text: w.text.trim(), startMs: Math.round((Number(w.start)||0)*1000), endMs: Math.round((Number(w.end)||0)*1000) }));
let job = null;
try { job = JSON.parse($('Code in JavaScript').first().json.job_json); } catch (e) { job = null; }
if (job && captions.length) { job.captions = captions; }
const out = Object.assign({}, $('Code in JavaScript').first().json);
if (job) { out.job_json = JSON.stringify(job); }
out.caption_count = captions.length;
const bin = $('Convert text to speech').first().binary;
return [{ json: out, binary: bin }];

const srcs=[['CoinDesk','RSS A'],['Cointelegraph','RSS B'],['Decrypt','RSS C']];
let all=[];
for(const [name,node] of srcs){ let items=[]; try{ items=$(node).all().map(i=>i.json);}catch(e){} items.forEach(it=>{ all.push({source:name,title:(it.title||'').toString(),link:(it.link||it.guid||'').toString(),snippet:(it.contentSnippet||it.content||'').toString().replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim().slice(0,220),date:it.isoDate||it.pubDate||''}); }); }
all=all.filter(x=>x.title&&x.link);
if(!all.length) throw new Error('Combine Feeds: no RSS stories collected');
all.sort((a,b)=> new Date(b.date||0)-new Date(a.date||0));
all=all.slice(0,20);
// variety: shuffle the recent pool and sample so each run rotates
for(let i=all.length-1;i>0;i--){const k=Math.floor(Math.random()*(i+1));const t=all[i];all[i]=all[k];all[k]=t;}
all=all.slice(0,5);
const candidatesText=all.map((x,i)=>(i+1)+'. ['+x.source+'] '+x.title+'\n   '+x.snippet+'\n   LINK: '+x.link).join('\n\n');
return [{ json: { candidates: all, candidatesText } }];

const raw=$input.first().json.content[0].text;
const s=raw.indexOf('{'); const e=raw.lastIndexOf('}');
const sel=JSON.parse(raw.slice(s,e+1));
return [{ json: { link: sel.link, title: sel.title||'', source_url: sel.link, reason: sel.reason||'' } }];
